lifecycle.after:
const host = document.createElement('div');
const shadow = host.attachShadow({mode: 'open'});
shadow.innerHTML = '<style>:host{all:initial;position:fixed;bottom:20px;right:20px;z-index:2147483646}section{font:14px system-ui;color:#222;background:#fff;border:1px solid #ccc;border-radius:10px;padding:10px;box-shadow:0 3px 16px #0002;display:flex;gap:8px;align-items:center}button,select{font:inherit;padding:4px}button{cursor:pointer}</style><section aria-label="Video speed controls"><select aria-label="Video"></select><button aria-label="Decrease speed">−</button><output aria-live="polite">1×</output><button aria-label="Increase speed">+</button><button>Reset</button><button aria-label="Hide video controls">×</button></section>';
document.documentElement.append(host);
const picker = shadow.querySelector('select');
const buttons = shadow.querySelectorAll('button');
const output = shadow.querySelector('output');
const original = new Map();
let videos = [], dismissed = false;
const refresh = () => {
 videos = Array.from(document.querySelectorAll('video')).filter(video => video.getClientRects().length && video.getBoundingClientRect().width >= 160);
 const previous = picker.value;
 picker.replaceChildren(...videos.map((video,index) => { const option=document.createElement('option'); option.value=String(index); option.textContent='Video ' + (index+1); return option; }));
 if (videos[Number(previous)]) picker.value=previous;
 host.style.display = videos.length && !dismissed ? '' : 'none';
 const video=videos[Number(picker.value) || 0];
 output.textContent = video ? Number(video.playbackRate.toFixed(2)) + '×' : '1×';
};
const change = delta => {
 const video=videos[Number(picker.value) || 0]; if(!video) return;
 if(!original.has(video)) original.set(video,video.playbackRate);
 try { video.playbackRate=delta===0 ? 1 : Math.max(0.25,Math.min(4,Math.round((video.playbackRate+delta)*100)/100)); output.textContent=video.playbackRate+'×'; } catch { output.textContent='Unavailable'; }
};
context.listen(buttons[0],'click',()=>change(-0.25));
context.listen(buttons[1],'click',()=>change(0.25));
context.listen(buttons[2],'click',()=>change(0));
context.listen(buttons[3],'click',()=>{dismissed=true;host.style.display='none';});
context.listen(picker,'change',refresh);
context.setInterval(refresh,2000);
context.onCleanup(()=>{host.remove();for(const [video,rate] of original) { if(video.isConnected) try {video.playbackRate=rate;} catch {} }});
refresh();
